@patch("vunnel.providers.alma.git.GitWrapper.clone_repo")
@patch("vunnel.providers.alma.git.GitWrapper.delete_repo")
def test_fix_dates_from_published(mock_git_delete, mock_git_clone, helpers, auto_fake_fixdate_finder):
    workspace = helpers.provider_workspace_helper(name=Provider.name())
    shutil.copytree(helpers.local_dir("test-fixtures"), workspace.input_dir, dirs_exist_ok=True)
    parser = Parser(ws=workspace, fixdater=auto_fake_fixdate_finder)
    seen = 0
    for _, _, record in parser.get():
        assert record["database_specific"]["anchore"] == {"record_type": "advisory"}
        expected = record["published"][:10]
        for affected in record["affected"]:
            for r in affected["ranges"]:
                fixed = [e["fixed"] for e in r["events"] if "fixed" in e]
                if not fixed:
                    continue
                fixes = r["database_specific"]["anchore"]["fixes"]
                assert fixes == [{"version": v, "date": expected, "kind": "advisory"} for v in fixed]
                seen += 1
    assert seen > 0
E
PYTHONPATH=src .venv/bin/python -m pytest -q tests/unit/providers/alma 2>&1 | tail -15
